-- Additive, private-only daily owner authority; no provider grants or old-row changes.
CREATE TABLE personal_daily_contracts (contract_hash TEXT PRIMARY KEY, source_id TEXT NOT NULL, contract_json TEXT NOT NULL CHECK(json_valid(contract_json)));
CREATE TRIGGER personal_daily_contract_immutable BEFORE UPDATE ON personal_daily_contracts BEGIN SELECT RAISE(ABORT,'immutable_daily_contract'); END;
CREATE TABLE personal_daily_runs (ordinal INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT UNIQUE NOT NULL, source_id TEXT NOT NULL, day TEXT NOT NULL, synthetic INTEGER NOT NULL CHECK(synthetic IN (0,1)), contract_hash TEXT NOT NULL REFERENCES personal_daily_contracts(contract_hash), started_at TEXT NOT NULL, observed_at TEXT, state TEXT NOT NULL CHECK(state IN ('partial','complete','failed','purging','purged')), record_count INTEGER, evidence_hash TEXT, evidence_expires_at TEXT NOT NULL, reason TEXT, lease_token TEXT, lease_until TEXT, exported_at TEXT, export_expires_at TEXT, UNIQUE(source_id,day,synthetic));
CREATE INDEX personal_daily_export ON personal_daily_runs(source_id,state,exported_at,ordinal);
CREATE TRIGGER personal_daily_run_immutable BEFORE UPDATE OF run_id,source_id,day,synthetic,contract_hash,started_at,evidence_expires_at ON personal_daily_runs BEGIN SELECT RAISE(ABORT,'immutable_daily_run'); END;
CREATE TABLE personal_daily_observations (observation_id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES personal_daily_runs(run_id), record_key TEXT NOT NULL, record_hash TEXT NOT NULL, observed_at TEXT NOT NULL, recorded_at TEXT NOT NULL, previous_observation_id TEXT, change_kind TEXT NOT NULL CHECK(change_kind IN ('first_seen','reobserved','revised')), domain_json TEXT NOT NULL CHECK(json_valid(domain_json)), UNIQUE(run_id,record_key));
CREATE INDEX personal_daily_record ON personal_daily_observations(record_key,observed_at);
CREATE TRIGGER personal_daily_observation_immutable BEFORE UPDATE ON personal_daily_observations BEGIN SELECT RAISE(ABORT,'immutable_daily_observation'); END;
CREATE TRIGGER personal_daily_observation_retention BEFORE DELETE ON personal_daily_observations WHEN (SELECT state FROM personal_daily_runs WHERE run_id=OLD.run_id) != 'purging' BEGIN SELECT RAISE(ABORT,'daily_retention_required'); END;
CREATE TABLE personal_daily_monitor (source_id TEXT PRIMARY KEY, receipt_at TEXT, receipt_hash TEXT, state TEXT NOT NULL, checked_at TEXT NOT NULL, details_json TEXT NOT NULL CHECK(json_valid(details_json)));
